import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;

public class TwoSum {

    // 暴力解法：O(n²) / O(1)
    public int[] twoSumBrute(int[] nums, int target) {
        for (int i = 0; i < nums.length; i++) {
            for (int j = i + 1; j < nums.length; j++) { // j 从 i+1 避免自配
                if (nums[i] + nums[j] == target) {
                    return new int[]{i, j};
                }
            }
        }
        return new int[]{}; // 题目保证有解，理论上不会走到这
    }

    // 哈希表解法：O(n) / O(n)
    public int[] twoSumHash(int[] nums, int target) {
        Map<Integer, Integer> map = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            int complement = target - nums[i];
            if (map.containsKey(complement)) { // ① 先查：complement 来自更早元素
                return new int[]{map.get(complement), i};
            }
            map.put(nums[i], i);              // ② 再存：当前元素留给后面配对
        }
        return new int[]{};
    }

    public static void main(String[] args) {
        TwoSum s = new TwoSum();
        System.out.println(Arrays.toString(s.twoSumHash(new int[]{2,7,11,15}, 9)));  // [0, 1]
        System.out.println(Arrays.toString(s.twoSumHash(new int[]{3,3}, 6)));         // [0, 1]
    }
}
